            ['الطلبات بتوصل بالبريد الإلكتروني؟', "تصلك تأكيدات البريد عند توفر خدمة البريد — أما المتابعة الأساسية فمن «طلباتي» داخل الحساب.", ['بريد', 'ايميل تأكيد', 'mail']],
            ['شو معنى NDF بكود الطلب؟', "اختصار اسم متجر نداف NADAF — كل طلب يحمل توقيع متجرنا.", ['معنى ndf', 'وشو ndf']],
            ['بتسلموا يوم الجمعة؟', "التسليم الإلكتروني متواصل، والتوصيل الجمعة حسب جدول المندوبين — اسألنا عن منطقتك.", ['الجمعة', 'اجازة', 'عطلة']],
            ['بدي أعرف رصيد قسيمة الحوالة؟', "راجع شبكة الحوالة (شام كاش/بنك) — أما بالمتجر فنثبت قبضك فور اعتماد الإثبات.", ['رصيد الحوالة', 'قسيمة']],
            ['بيانات الدفع آمنة عندكم؟', "نعم — لا نحفظ أرقام بطاقات، والإيصالات تُخزن مشفرة الوصول لأغراض طلبك فقط.", ['آمنة الدفع', 'حفظ الدفع']],
        ];

        $rows = [];
        $sort = 0;
        foreach (array_merge($QA, $extra) as [$q, $a, $kws]) {
            $rows[] = [
                'question' => $q,
                'answer' => $a,
                'keywords' => json_encode($kws, JSON_UNESCAPED_UNICODE),
                'is_active' => true,
                'sort_order' => $sort++,
                'created_at' => now(),
                'updated_at' => now(),
            ];
        }

        // كرر أول 61 سؤالًا بصيغ مختلفة حتى نصل 100 دون حشو مكرر نصيًا
        $variants = [
            ['وين بلاقي كرافات حلوة؟', 'كيف أطلب كرافة؟'],
            ['بتوصلوا دمشق؟', 'بتوصلوا حلب؟'],
            ['شحون سعر الصرف اليوم؟', 'شو سعر الدولار عندكم؟'],
            ['بدي أعرف وين طلبي؟', 'طلبي وين وصل؟'],
            ['كيف بستخدم الكوبون؟', 'وين حقل الخصم؟'],
            ['بقدر أدفع واتساب؟', 'بتقبلوا تحويل واتساب؟'],
            ['شو خامة الكرافات؟', 'الكরافة قطن ولا حرير؟'],
            ['متى ينشحن طلبي؟', 'ايمتى بيتشحن الطلب؟'],
            ['بدي فاتورة باسم الشركة؟', 'فيكوا تفاتيروا للشركة؟'],
            ['بفي خصم للطلبات الكبيرة؟', 'شو خصم الجملة؟'],
        ];
        foreach ($variants as $i => [$v1, $v2]) {
            $src = $rows[$i % count($QA)];
            $rows[] = ['question' => $v1, 'answer' => $src['answer'], 'keywords' => $src['keywords'], 'is_active' => true, 'sort_order' => $sort++, 'created_at' => now(), 'updated_at' => now()];
            $rows[] = ['question' => $v2, 'answer' => $src['answer'], 'keywords' => $src['keywords'], 'is_active' => true, 'sort_order' => $sort++, 'created_at' => now(), 'updated_at' => now()];
        }

        // زرع فعلي: 100 سؤال (قصّ الزيادة)
        $rows = array_slice($rows, 0, 100);

        // حماية من التكرار إن أعيد التشغيل
        foreach ($rows as $row) {
            ChatQuestion::updateOrCreate(['question' => $row['question']], $row);
        }

        $this->command?->info('تم زرع '.count($rows).' سؤال/جواب للشات العائم');
    }
}
